let bubbleCfg = require("TheEvil_BubbleCfg");

cc.Class({
    extends: cc.Component,

    properties: {
        _id:0,
        _type: 0,
        _cfg:null,
        _moveNode : null,
        _pubbleItems: [],
        _currPosIndex: -1,
        _nextPosIndex: -1,

        _bubbleSpine:null,
        _baozaSpine:null,
        _smallCoinNode: 0,
        _bigCoinNode: 0,
        _coinNum: 0,
        _isKeepMove:true,
        _showTriggerAnimation:false,
        _jackpot:null,
        _index:0,
        _click:true,
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    onLoad () {
        this._moveNode = this.node.getChildByName("move_node");
        this._coinNode = this._moveNode.getChildByName("coin");
        this._smallCoinNode = this._coinNode.getChildByName("coin_small");
        this._smallCoinNode.active = false;
        this._bigCoinNode = this._coinNode.getChildByName("coin_big");
        this._bigCoinNode.active =false;
        this._pickCoinNode = this._coinNode.getChildByName("coin_pick");
        this._pickCoinNode.active =false;
        
        this._pubbleItems = []
        for (let index = 1; index < 7; index++) {
            let item = this._moveNode.getChildByName("bubble_"+index);
            item.active = false;
            item.setPosition(cc.v2(0,0));
            this._pubbleItems.push(item);
        }
        this.node.on(cc.Node.EventType.TOUCH_START,this.onEventStart,this)
    },

    bindBubble(id, posIndex, nextIndex, type, coin){  // 0: 普通， 1：mini, 2:minor, 3: major, 4:grand,5: 小恶魔
        this._id = id;
        this._type = type;
        this._cfg = bubbleCfg.bubbleData[id];
        this._currPosIndex = posIndex;
        this.node.active = true;
        this._click = true
        this._pubbleItems[this._type].active = true;
        this._bubbleSpine = this._pubbleItems[this._type].getChildByName("bubble_spine")
        this._bubbleSpine.active = true;
        this._baozaSpine = this._pubbleItems[this._type].getChildByName("baoza_spine")
        this._baozaSpine.active = false;
        this._jackpot = this._pubbleItems[this._type].getChildByName("jackpot")
        if(this._jackpot){
            this._jackpot.active = true
        }
        
        this.node.setScale(this._cfg.size);
        this.node.setPosition(new cc.v2(this._cfg.route[this._currPosIndex].x, this._cfg.route[this._currPosIndex].y));
        if(nextIndex > 0){
            if(nextIndex < this._cfg.route.length){
                this._nextPosIndex = nextIndex;
            }else{
                this._nextPosIndex = -1;
            }
        }else{
            if(this._currPosIndex + 1 < this._cfg.route.length){
                this._nextPosIndex = this._currPosIndex + 1;
            }else{
                this._nextPosIndex = -1;
            }
        }
        if(this._type == 0){
             //泡泡内金币
            let mult = Math.floor(coin/cc.vv.gameData.GetTotalBet());
            this._coinNum = coin;
            if(mult < 10){
                this._bigCoinNode.active =false;
                this._smallCoinNode.active = true;
                this._smallCoinNode.getComponent(cc.Label).string = Global.convertNumToShort(coin,1000,1,null,1000); 
            }else{
                this._smallCoinNode.active =false;
                this._bigCoinNode.active = true;
                this._bigCoinNode.getComponent(cc.Label).string = Global.convertNumToShort(coin,1000,1,null,1000); 
            }
        }  
    },

    moveBubble(){
        this._coinNode.active = true
        if(this._nextPosIndex >= 0){
            this._currPosIndex = this._nextPosIndex;
            let movePosition = cc.v2(this._cfg.route[this._nextPosIndex].x,this._cfg.route[this._nextPosIndex].y);
            this.node.runAction(cc.sequence(cc.moveTo(2,movePosition),cc.callFunc(()=>{
                this._moveNode.stopAllActions();
                this._moveNode.setPosition(cc.v2(0,0));
                this._bubbleSpine.getComponent(sp.Skeleton).setAnimation(0,"animation1",true);
            })));
            this._moveNode.runAction(cc.repeatForever(cc.sequence(cc.moveBy(0.5,cc.v2(-50,0)),cc.moveBy(1,cc.v2(100,0)), cc.moveBy(0.5,cc.v2(-50,0)))));

            let animationName = this._id%2 == 0 ? "animation4" : "animation5"
            this._bubbleSpine.getComponent(sp.Skeleton).setAnimation(0,animationName,true);
            
            if(this._currPosIndex + 1 < this._cfg.route.length){
                this._nextPosIndex = this._currPosIndex + 1;
            }else{
                this._nextPosIndex = -1;
            }
            this._isKeepMove = true
            return false
        }else{
            let moveEndPosition = cc.v2(this._cfg.route[0].x,600);
            let posMoveSpace =  this.node.parent.convertToWorldSpaceAR(moveEndPosition);
            this.node.runAction(cc.spawn(cc.moveTo(5,moveEndPosition),cc.sequence(cc.delayTime(2.8),cc.callFunc(()=>{
                Global.TheEvilGameControl.collectBonusControl.shotBubble(posMoveSpace,1.2);
            }),cc.delayTime(2.2),cc.callFunc(()=>{
                this.playbrokenBubble();
            }))))
            this._bubbleSpine.getComponent(sp.Skeleton).setAnimation(0,"animation3",true);
            this._isKeepMove = false
            return true
        }
    },

    async stopBubble(){
        if (this._isKeepMove) {
            let movePosition = cc.v2(this._cfg.route[this._currPosIndex].x,this._cfg.route[this._currPosIndex].y);
            this.node.stopAllActions();
            this._moveNode.stopAllActions();
            this._moveNode.setPosition(cc.v2(0,0));
            this._bubbleSpine.getComponent(sp.Skeleton).setAnimation(0,"animation1",true);
            this.node.setPosition(movePosition);
        }
    },

    async playbrokenBubble(){
        this._bubbleSpine.active = false;
        this._smallCoinNode.active = false;
        this._bigCoinNode.active =false;
        this._baozaSpine.active = true;
        if(this._jackpot){
            this._jackpot.active = false
        }
        let animationName = this._type == 5 ? "animation1" : "animation";
        this._baozaSpine.getComponent(sp.Skeleton).setAnimation(0,animationName,false);
        this._baozaSpine.getComponent(sp.Skeleton).setCompleteListener(()=>{
            this.node.removeFromParent();
            this.node.destroy()
        });
    },

    async playActiveBubble(){
        this._coinNode.active = false;
        this._bubbleSpine.getComponent(sp.Skeleton).setAnimation(0,"animation2",true);
    },

    async setCoinActive(isActive){
        this._coinNode.active = isActive;
    },


    //创建点击泡泡
    async creatPickBubble(id,idx){  
        this._id = id;
        this._index = idx || 0
        this._type = 0;
        this._cfg = bubbleCfg.bubbleData[id];
        this.node.active = true;
        this._click = false
        this._pubbleItems[this._type].active = true;
        this._bubbleSpine = this._pubbleItems[this._type].getChildByName("bubble_spine")
        this._bubbleSpine.active = true;
        this._baozaSpine = this._pubbleItems[this._type].getChildByName("baoza_spine")
        this._baozaSpine.active = false;

        this.node.setScale(this._cfg.size); 
        this.node.setPosition(new cc.v2(this._cfg.pickPosX, -cc.winSize.height/2));
        this._bubbleSpine.getComponent(sp.Skeleton).setAnimation(0,this._cfg.pickMoveAnimation,true);
        let movePosition = cc.v2(this._cfg.pickPosX,1300);
        this.node.runAction(cc.sequence(cc.moveTo(10,movePosition),cc.callFunc(()=>{
            Global.TheEvilGameControl.bubbleControl.deleteBubble(this.node)
            this.node.removeFromParent();
            this.node.destroy()
        })));
    },

    onClick(){
        Global.TheEvilGameControl.bubbleControl._pickBubbleCnt = 0;

        this.node.stopAllActions();
        this._bubbleSpine.active = false;
        this._baozaSpine.active = true;
        this._baozaSpine.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
        let pickInfo = Global.TheEvilGameControl.bubbleControl.clickPickBubble()
        if(pickInfo){
            Global.TheEvilGameControl.bubbleControl.deleteBubble(this.node)
            if(pickInfo.type == 0){  //普通气泡
                if(pickInfo.index == 19){
                    Global.TheEvilGameControl.pickGameControl.updateTips(3,pickInfo.index);
                }else{
                    Global.TheEvilGameControl.pickGameControl.updateTips(2,pickInfo.index);
                }  
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bubble_reveal)
                this._pickCoinNode.active = true;
                this._pickCoinNode.getComponent(cc.Label).string = Global.convertNumToShort(pickInfo.coin,1000,1,null,1000); 
                this._baozaSpine.runAction(cc.sequence(cc.delayTime(0.3),cc.callFunc(()=>{
                    let startPos = this.node.getPosition();
                    let bezier = [cc.v2(startPos.x/2,startPos.y+100),cc.v2(startPos.x/2,startPos.y+100),cc.v2(0, -cc.winSize.height/2 + 180)];
                    this.node.runAction(cc.bezierTo(0.5, bezier));
                    this._pickCoinNode.runAction(cc.sequence(cc.scaleTo(0.5, 0).easing(cc.easeBackIn()),cc.callFunc(()=>{
                        let currentCoin = cc.vv.gameData.GetBottomScript().getCurrentWin()
                        cc.vv.gameData.GetBottomScript().ShowWin(currentCoin + pickInfo.coin,0.8,null,null)
                        this.node.removeFromParent();
                        this.node.destroy()
                    })));
                })));
            }else if(pickInfo.type == 1){ //普通气泡结束
                Global.TheEvilGameControl.pickGameControl.updateTips(4,pickInfo.index);
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bubble_reveal)
                this._pickCoinNode.active = true;
                this._pickCoinNode.getComponent(cc.Label).string = Global.convertNumToShort(pickInfo.coin,1000,1,null,1000); 
                Global.TheEvilGameControl.bubbleControl.stopPickBubble()
                this._baozaSpine.runAction(cc.sequence(cc.delayTime(0.3),cc.callFunc(()=>{
                    let startPos = this.node.getPosition();
                    let bezier = [cc.v2(startPos.x/2,startPos.y+100),cc.v2(startPos.x/2,startPos.y+100),cc.v2(0, -cc.winSize.height/2 + 180)];
                    this.node.runAction(cc.bezierTo(0.5, bezier));
                    this._pickCoinNode.runAction(cc.sequence(cc.scaleTo(0.5, 0).easing(cc.easeBackIn()),cc.callFunc(()=>{
                        let currentCoin = cc.vv.gameData.GetBottomScript().getCurrentWin()
                        cc.vv.gameData.GetBottomScript().ShowWin(currentCoin + pickInfo.coin,0.8,null,null)
                        this.node.removeFromParent();
                        this.node.destroy()
                        Global.TheEvilGameControl.pickGameControl.showEndGame();
                        
                    })));
                })));
            }else if(pickInfo.type == 2){  //小恶魔气泡结束
                let posStartWorld = this.node.convertToWorldSpaceAR(cc.v2(0.0));
                Global.TheEvilGameControl.pickGameControl.updateTips(4,pickInfo.index);
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bubble_scatter)
                Global.TheEvilGameControl.bubbleControl.stopPickBubble();
                Global.TheEvilGameControl.pickGameControl.showEmoCoin(posStartWorld,pickInfo.coin);
                this.scheduleOnce(()=>{
                    this.node.removeFromParent();
                },0.3)
            }
        }
    },

    showTriggerAnimation(pointIdx){
        if(this._showTriggerAnimation){
            return
        }
        let pos = this.node.position
        for (let i = 0; i < this._cfg.route.length; i++) {
            const route = this._cfg.route[i];
            if(route.x === pos.x && route.y === pos.y){
                if(route.point.indexOf(pointIdx) !== -1){
                    this._showTriggerAnimation = true
                    cc.tween(this.node).repeatForever(cc.tween(this.node).to(0.3,{scale:this._cfg.size*1.2},{easing:"backOut"}).to(0.2,{scale:this._cfg.size})).start()
                    if(this._type > 0){  //非普通气泡
                        let slots = cc.vv.gameData.GetSlotsScript()
                        slots.ShowJackpotEffect(true)
                    }
                }
                break
            }
        }
    },

    stopTriggerAnimation(){
        this.node.stopAllActions()
        this.node.setScale(this._cfg.size)
        this._showTriggerAnimation = false
        let slots = cc.vv.gameData.GetSlotsScript()
        slots.ShowJackpotEffect(false)
    },

    onEventStart(event){
        if(this._click){  //保证只点击一次
            return
        }
        this._click = true
        this.onClick()
    },
});
