cc.Class({
    extends: cc.Component,

    properties: {
        pick_bubble_node: {
            default: null,        // The default value will be used only when the component attaching
            type: cc.Node, // optional, default is typeof default
        },
        items_bubble_node: {
            default: null,        // The default value will be used only when the component attaching
            type: cc.Node, // optional, default is typeof default
        },
        items_bubble_mask_node: {
            default: null,        // The default value will be used only when the component attaching
            type: cc.Node, // optional, default is typeof default
        },
        _activeBubbleCmps  : [],       // 激活气泡对象
        _bubbleTemplate:null,
        _pickIndex:0,
        _pickData: null,
        _pickBubbleList:[],   //点击气泡列表
        _touchId:null,
        _pickBubbleCnt:0,
    },


    // LIFE-CYCLE CALLBACKS:
    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    onLoad () {
        this._bubbleTemplate = cc.find("bubble",this.node);
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvGameAction,this);   
    },

    onDestroy()
    {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvGameAction,false,this);
    },

    //收到子游戏操作
    async onRecvGameAction(msg){
        if(msg.code == 200){
           
        }
    },

    //生成新气泡
    generateBubble(bubbleData){
        for (let data of bubbleData) {
            if(data.preIndex == 0){
                 let bubbleItem =  cc.instantiate(this._bubbleTemplate);
                bubbleItem.parent = this.items_bubble_node;
                bubbleItem.active = true;
                let bubbleCmp = bubbleItem.getComponent("TheEvil_Bubble");
                bubbleCmp.bindBubble(data.id,data.preIndex,data.currIndex,data.type, data.coin);
                this._activeBubbleCmps.push(bubbleCmp);
            }
        }
    },

    //更据下注额更新气泡
    creatCurrentBubble(){
        this.clearCurrentBubble()
        let index = cc.vv.gameData.GetBetIdx() - 1
        let bubbleInfo = cc.vv.gameData.allBububbleInfo[index]
        this.createBubble(bubbleInfo)
    },

    createBubble(bubbleInfo){
        if(bubbleInfo && bubbleInfo.length > 0){
            for (let data of bubbleInfo) {
                let bubbleItem =  cc.instantiate(this._bubbleTemplate);
                bubbleItem.parent = this.items_bubble_node;
                bubbleItem.active = true;
                let bubbleCmp = bubbleItem.getComponent("TheEvil_Bubble");
                bubbleCmp.bindBubble(data.id,data.currIndex,data.nextIndex,data.type, data.coin);
                this._activeBubbleCmps.push(bubbleCmp);
            }
        }
    },

    clearCurrentBubble(){
        this._activeBubbleCmps = [];
        this.items_bubble_node.removeAllChildren()
        this.items_bubble_mask_node.removeAllChildren()
    },

    //移动气泡
    updateActiveBubble(){
        for (let index = this._activeBubbleCmps.length - 1; index >= 0; index--) {
            if(this._activeBubbleCmps[index].moveBubble()){   //气泡已经移出去了；要从数组中删除
                this._activeBubbleCmps.splice(index,1);
            }
        }
    },

    //遮挡气泡
    maskAllActiveBubble(isMask){
        if(isMask){
            for (let cmp of this._activeBubbleCmps) {
                cmp.node.parent = this.items_bubble_mask_node;
                cmp.setCoinActive(false)
            }
        }else{
            for (let cmp of this._activeBubbleCmps) {
                cmp.node.parent = this.items_bubble_node;
                cmp.setCoinActive(true)
            }
        }
    },

    //显示中奖气球动画
    showWinBubbleAnimation(pointIdx){
        for (let j = 0; j < this._activeBubbleCmps.length; j++) {
            const bubble = this._activeBubbleCmps[j];
            bubble.showTriggerAnimation(pointIdx)
        }
    },

    //隐藏所有气球动画
    hideAllBubbleAnimation(){
        for (let j = 0; j < this._activeBubbleCmps.length; j++) {
            const bubble = this._activeBubbleCmps[j];
            bubble.stopTriggerAnimation()
        }
    },

    //手动停止；设置气泡位置
    stopActiveBubble(){
        for (let cmp of this._activeBubbleCmps) {
            cmp.stopBubble();
        }
    },

     //生成pick气泡
    generatePickBubble(id,idx){
        let bubbleItem =  cc.instantiate(this._bubbleTemplate);
        bubbleItem.parent = this.pick_bubble_node;
        bubbleItem.active = true;
        let bubbleCmp = bubbleItem.getComponent("TheEvil_Bubble");
        bubbleCmp.creatPickBubble(id,idx);
        this._pickBubbleList.push(bubbleItem)
    },
    
    //发射pick气泡
    async launchPickBubble(data){  
        this._pickData = data.coinsData
        this._pickIndex = data.pickIndex;
        let idList = [1,1,1,2,2,2,3,3,3,4,4,4,5,5,5,6,7,8,9];
        let paopaoIndex = 0
        this._pickBubbleList = []
        this._pickBubbleCnt = 0;
        while(this._pickData.length > 0){
            let id = idList[parseInt(Math.random()*idList.length)];
            this.generatePickBubble(id,paopaoIndex);
            paopaoIndex++;
            this._pickBubbleCnt += 1;

            if(cc.vv.gameData.isNeedAutoPlay() && this._pickBubbleCnt > 10) {
                this._pickBubbleCnt = 0;
                let paopao = this._pickBubbleList[Global.random(0,this._pickBubbleList.length - 1)];
                paopao.emit(cc.Node.EventType.TOUCH_START);
            }

            await this.awaitTime(0.5);
        }
    },

    deleteBubble(item){
        for (let i = 0; i < this._pickBubbleList.length; i++) {
            const element = this._pickBubbleList[i];
            if(element == item){
                this._pickBubbleList.splice(i,1)
                return
            }
        }
    },

     //pick气泡
    clickPickBubble(){  //type:  0:普通气泡；  1普通气泡结束；  2小恶魔气泡结束
        let info = {}
        if(this._pickData.length > 0){
            this._pickIndex = this._pickIndex + 1;
            let tempData = this._pickData.splice(0,1)
            info.type = tempData[0].type;
            info.coin = tempData[0].coin;
            info.index = this._pickIndex;
        
            let req = {c: MsgId.SLOT_SUBGAME_DATA};
            req.uid = Global.playerData.uid;
            req.gameid = cc.vv.gameData.getGameId();
            req.data = {};
            req.data.rtype = 1;
            cc.vv.NetManager.send(req);
            return info;
        }else{
            return null;
        }
    },

     //停止pick气泡
    async stopPickBubble(){
        for (let i = 0; i < this._pickBubbleList.length; i++) {
            const element = this._pickBubbleList[i];
            if(element){
                element.parent = null
            }
        }
        this._pickBubbleList = []
    },

    // update (dt) {},
});
