/**
 * 符号控制
 */
let jackpotMusic = ["mini_jackpot","minor_jackpot","major_jackpot","grand_jackpot"]
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _bonusIndex:0,
        _BubbleCoin:0,
        _BubbleJpId:0,
    },

    SetCoin(coin){
        this._data = coin
        let cfg = cc.vv.gameData.getGameCfg()
        let coinLable =  cc.find("coin", this.node)
        if(cfg.symbol[this._id].coin){
            coinLable.active = true
            coinLable.getComponent(cc.Label).string = Global.convertNumToShort(this._data,1000,1,null,1000); 
        }else{
            coinLable.active = false
        }
    },

    StopMoveEnd(){
        this._super()
        this.playidleAnimation()
    },

    //待机动画
    playidleAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].idle_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._state = "idle";
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            aniNode.zIndex = cfg.symbol[id].idle_ani.zIndex - this._symbolIdx + this._reelIdx*10;
            isPlay = true
            if(cfg.symbol[id].idle_ani.name != ""){
                let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
                topShowNode.active = true
                aniNode.zIndex = cfg.symbol[id].idle_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].idle_ani.name,true)
                }
            }else{
                cc.find(cfg.symbol[id].win_node,aniNode).active = false
                cc.find(cfg.symbol[id].node,aniNode).active = true
            }
        }
        return isPlay
    },

    //触发动画
    playTriggerAnimation(){  
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._state = "trigger";
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].trigger_ani.name,true)
                }
            }
        }
        return isPlay
    },

    //消失动画  disappear_ani
    playDisappearAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].disappear_ani){
            if(cfg.symbol[id].disappear_ani.name != ""){
                this._state = "disappear";
                let aniNode = this.setAnimationToTop(true)
                aniNode.active = true
                let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
                topShowNode.active = true
                aniNode.zIndex = cfg.symbol[id].disappear_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){ 
                    this.node.active = true
                    if(this._showNode){
                        this._showNode.active = true
                    } 
                    nodeSp.setAnimation(0,cfg.symbol[id].disappear_ani.name,false)
                }
            }else{
                this.setAnimationToTop(false)
            }
        }
        return isPlay
    },

    //气球激活七角星轮盘
    playBubbleAnimation(coin,jpId){
        let isPlay = false
        let id = this._id
        this._BubbleCoin = coin
        this._BubbleJpId = jpId
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_bubble){
            isPlay = true
            if(this._showNode){
                this._showNode.active = false
            }
            this._state = "bubbleAnimation";
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            aniNode.zIndex = cfg.symbol[id].trigger_bubble.zIndex - this._symbolIdx + this._reelIdx*10;
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            let nodeSp = topShowNode.getComponent(sp.Skeleton)
            nodeSp.setAnimation(0,cfg.symbol[id].trigger_bubble.name,false)
            nodeSp.addAnimation(0,cfg.symbol[id].trigger_bubble_idle.name,true)
           
            switch (jpId) {
                case 1:
                case 2:
                case 3:
                case 4:{
                    let jp = aniNode.getChildByName("jp_"+jpId);
                    jp.active = true
                    jp.setScale(0.9);
                    jp.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(0.7,1.1,1.1),cc.scaleTo(0.7,0.9,0.9))));
                    Global.SlotsSoundMgr.playEffect(jackpotMusic[jpId - 1])
                }break   
                default:{
                    //金币动画
                    let smallCoinNode = aniNode.getChildByName("coin_small");
                    let bigCoinNode = aniNode.getChildByName("coin_big");
                    //金币
                    let mult = Math.floor(coin/cc.vv.gameData.GetTotalBet());
                    if(mult < 10){
                        smallCoinNode.active = true;
                        smallCoinNode.getComponent(cc.Label).string = Global.convertNumToShort(coin,1000,1,null,1000); 
                        smallCoinNode.setScale(0.9);
                        smallCoinNode.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(0.7,1.1,1.1),cc.scaleTo(0.7,0.9,0.9))));
                    }else{
                        bigCoinNode.active = true;
                        bigCoinNode.getComponent(cc.Label).string = Global.convertNumToShort(coin,1000,1,null,1000); 
                        bigCoinNode.setScale(0.9);
                        bigCoinNode.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(0.7,1.1,1.1),cc.scaleTo(0.7,0.9,0.9))));
                    }
                }break
            }
        }
        return isPlay
    },

    setAnimationToTop(isTop){
        if(this._topAniNode){
            if (isTop) {
                let cloneNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s",this._symbolIdx,this._reelIdx),this._topAniNode);
                if (cloneNode) {
                    cloneNode.removeFromParent()
                    cloneNode.destroy()
                }
                cloneNode = cc.instantiate(this.node)
                let wordPos = this.node.convertToWorldSpaceAR(cc.v2(0.0));
                cloneNode.parent = this._topAniNode
                cloneNode.name = cc.js.formatStr("symbol_ani_%s_%s",this._symbolIdx,this._reelIdx)
                cloneNode.position = this._topAniNode.convertToNodeSpaceAR(wordPos)
                this.node.active = false
                return cloneNode
            }else{
                let showNode = cc.find(cc.js.formatStr("symbol_ani_%s_%s",this._symbolIdx,this._reelIdx),this._topAniNode);
                if (showNode) {
                    showNode.removeFromParent()
                    showNode.destroy()
                }
                this.node.active = true
                if(this._showNode){
                    this._showNode.active = true
                }
            } 
        }
        return this.node
    },

    Backup() {
        let backup = {};
        backup.symbolIdx = this._symbolIdx;
        backup.id = this._id;
        if (this._data) {
            backup.data = Global.copy(this._data);
        }
        backup.isKuang = this._isKuang;
        backup.state = this._state;
        backup.BubbleCoin = this._BubbleCoin
        backup.BubbleJpId = this._BubbleJpId
        return backup
    },

    //恢复到保存的状态
    Resume(backup) {
        if (!backup) return;
        this._symbolIdx = backup.symbolIdx;
        this._id = backup.id;
        this._data = Global.copy(backup.data);
        this.ShowKuang(backup.isKuang);
        this.ShowNormal();
        let state = backup.state;
        if (state == "win") {
            this.playWinAnimation();
        } else if (state == "stop") {
            this.playStopAnimation();
        } else if (state == "idle") {
            this.playidleAnimation();
        } else if (state == "trigger") {
            this.playTriggerAnimation();
        } else if (state == "disappear"){
            this.playDisappearAnimation()
        } else if (state == "bubbleAnimation"){
            this.playBubbleAnimation(backup.BubbleCoin,backup.BubbleJpId)
        }
    },

    // update (dt) {},
});
