cc.Class({
    extends: cc.Component,

    properties: {
        _gameUI:null,
        _pickKuang:null,
        _xiaoemo:null,
        _xiaoemoCoin:null,
        _coinLable:null,
        _suziLable:null,
        _textArr : [],

        _exitCallBack: null,
        _pickData: null,
        _bonusWinCoin:0,
        _activeTips:null,
        _tipText:null,
    },

    // LIFE-CYCLE CALLBACKS:
    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    onLoad () {
        this._gameUI = cc.find("Game_UI",this.node);
        this._gameUI.active = false;
        this._pickKuang =  cc.find("Game_UI/pick_kuang",this.node);
        this._xiaoemo = cc.find("Game_UI/xiaoemo_node/xiaoemo",this.node);
        this._xiaoemoCoin = cc.find("Game_UI/xiaoemo_coin",this.node);
        this._coinLable = cc.find("Game_UI/xiaoemo_coin/coin",this.node);
        this._suziLable = cc.find("Game_UI/pick_kuang/text_2/suzi",this.node);
        for (let index = 1; index < 5; index++) {
            let tempText = this._pickKuang.getChildByName("text_"+index);
            this._textArr.push(tempText);
        }
        this._tipText = cc.find("pick_a_bubble_text",this._gameUI)
    },

    async initData(data){
        this._pickData = data;
        this._bonusWinCoin = this._pickData.totaolWinCoin
        this._xiaoemoCoin.active = false;
        this._coinLable.active = false;
        this._xiaoemo.getComponent(sp.Skeleton).setAnimation(0,"idle",true);
        this.updateTips(1,this._pickData.pickIndex);
        await this.awaitTime(1);
        //生成气泡
        Global.TheEvilGameControl.bubbleControl.launchPickBubble(this._pickData);
    },

    async showEmoCoin(startWorldNode,coin){
        let posStartSpace = this._gameUI.convertToNodeSpaceAR(startWorldNode);
        this._xiaoemoCoin.active = true;
        this._xiaoemoCoin.setPosition(posStartSpace);
        this._xiaoemoCoin.setScale(0.3);
        this._xiaoemoCoin.getComponent(sp.Skeleton).setAnimation(0,"animation1",false);
        await this.awaitTime(0.8);
        this._xiaoemoCoin.getComponent(sp.Skeleton).setAnimation(0,"animation2",true);
        this._xiaoemoCoin.runAction(cc.spawn(cc.moveTo(0.5,cc.v2(0, 100)),cc.scaleTo(1,1)));
        this._xiaoemo.getComponent(sp.Skeleton).setAnimation(0,"skill02",false);
        await new Promise((sucess,failed)=>{
            this._xiaoemo.getComponent(sp.Skeleton).setCompleteListener(()=>{
                sucess()
                this._xiaoemo.getComponent(sp.Skeleton).setAnimation(0,"idle",true);
            });
        })
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.scatter_reveal)
        this._xiaoemoCoin.getComponent(sp.Skeleton).setAnimation(0,"animation3",false);
        await this.awaitTime(0.8);
        this._coinLable.active = true;
        this._coinLable.getComponent(cc.Label).string = Global.convertNumToShort(coin,1000,1,null,1000);
        this._xiaoemoCoin.getComponent(sp.Skeleton).setAnimation(0,"animation4",false);
        await this.awaitTime(0.2);

        let startPos = this._xiaoemoCoin.getPosition();
        let bezier = [cc.v2(startPos.x/2,startPos.y+100),cc.v2(startPos.x/2,startPos.y+100),cc.v2(0, -cc.winSize.height/2 + 180)];
        this._xiaoemoCoin.runAction(cc.spawn(cc.bezierTo(0.5, bezier),cc.scaleTo(0.5, 0).easing(cc.easeBackIn())));
        await this.awaitTime(0.5);
        let currentCoin = cc.vv.gameData.GetBottomScript().getCurrentWin()
        cc.vv.gameData.GetBottomScript().ShowWin(currentCoin + coin,0.8,null,null)
        await this.awaitTime(0.5);
        await Global.TheEvilGameControl.popupUIControl.showPickGameWinner(cc.vv.gameData.GetBottomScript().getCurrentWin())
        Global.TheEvilGameControl.popupUIControl.playEmoAnimation()
        await this.awaitTime(2);
        this.exitGame();
    },

    async showEndGame(){
        await this.awaitTime(0.5);
        await Global.TheEvilGameControl.popupUIControl.showPickGameWinner(cc.vv.gameData.GetBottomScript().getCurrentWin())
        Global.TheEvilGameControl.popupUIControl.playEmoAnimation()
        await this.awaitTime(2);
        this.exitGame();
    },

    async updateTips(type, index){  //1：开始状态； 2：更新次数； 3:最后一次； 4：结束
        for (let text of this._textArr) {
            text.active = false;
        }
        if (type == 1) {
            this._textArr[0].active = true;
            this._pickKuang.setScale(0.1);
            this._pickKuang.runAction(cc.sequence(cc.scaleTo(0.3,1), cc.delayTime(1.5),cc.scaleTo(0.3,0.1),cc.callFunc(()=>{
                this._textArr[0].active = false;
                this._textArr[1].active = true;
                this._activeTips = this._textArr[1]
                this._suziLable.getComponent(cc.Label).string = 20 - index;
            }),cc.scaleTo(0.3,1)));
        }else if(type == 2){
            this._textArr[1].active = true;
            this._activeTips = this._textArr[1]
            this._suziLable.getComponent(cc.Label).string = 20 - index;
        }else if(type == 3){
            this._pickKuang.setScale(1);
            this._pickKuang.stopAllActions();
            this._pickKuang.runAction(cc.sequence(cc.scaleTo(0.3,0.1),cc.callFunc(()=>{
                this._textArr[1].active = false;
                this._activeTips.active = false;
                this._textArr[2].active = true;
                this._activeTips = this._textArr[2]
            }),cc.scaleTo(0.3,1)));
        }else if(type == 4){
            this._pickKuang.setScale(1);
            this._pickKuang.stopAllActions();
            this._pickKuang.runAction(cc.sequence(cc.scaleTo(0.3,0.1),cc.callFunc(()=>{
                this._textArr[3].active = true;
                this._activeTips.active = false;
                this._textArr[3].active = true;
                this._activeTips = this._textArr[3]
            }),cc.scaleTo(0.3,1),cc.delayTime(1.5),cc.scaleTo(0.3,0)));
            this._tipText.active = false
        }
    },

    getBonusWinCoin(){
        return this._bonusWinCoin
    },

    exitGame(){
        if (cc.vv.gameData.isFreeGame()) {
            if(Global.TheEvilGameControl.collectBonusControl.isSuperBonus()){
                Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.super_bgm)
            }else{
                Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.free_bgm)
            }
        }else{
            Global.SlotsSoundMgr.playNormalBgm(true)
        }
        this._gameUI.active = false;
        if (this._exitCallBack) {
            this._exitCallBack(); 
        }
    },

    enterGame (data,  exitCallBack) {
        Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.pick_bgm)
        this._exitCallBack = exitCallBack;
        this._gameUI.active = true;
        this.initData(data);
        this._tipText.active = true
    },

    // update (dt) {},
});
