            let show_popup = this._popup.getChildByName("show_superBonus");
            show_popup.active = true;
            show_popup.setScale(1);

            let frame1 = show_popup.getChildByName("frame1");
            frame1.setScale(0);
            let frame2 = show_popup.getChildByName("frame2");
            frame2.setScale(0);
            let frame3 = show_popup.getChildByName("frame3");
            frame3.setScale(0);
            let frame4 = show_popup.getChildByName("frame4");
