    //superBonus
    showSuperBonusWinCoin(num){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.super_popclose)
            this._popup.active = true;
            let show_popup = this._popup.getChildByName("show_superBonusWinCoin");
            show_popup.active = true;
            show_popup.setScale(1);

            let frame1 = show_popup.getChildByName("frame1");
            frame1.setScale(0);
            let text_bg = show_popup.getChildByName("text_bg");
            text_bg.setScale(0);
            let frame4 = show_popup.getChildByName("frame4");
            frame4.setScale(0);
            let start = show_popup.getChildByName("start");
            start.setScale(0);
            let bg = show_popup.getChildByName("bg");
            bg.setScale(0.8);
         
            cc.tween(bg).to(0.1,{scale:1},{easing:"backOut"}).start()
            await this.awaitTime(0.1)
            let winLable = cc.find("coin",text_bg)
            this._startAddCoin = true
            Global.doRoallNumEff(winLable,Math.floor(num*0.1),num,2.5,()=>{
                this._startAddCoin = false
            },null,0,true);
            cc.tween(frame1).to(0.6,{scale:1},{easing:"backOut"}).start()
            cc.tween(text_bg).to(0.8,{scale:1},{easing:"backOut"}).start()
            cc.tween(frame4).to(0.6,{scale:1},{easing:"backOut"}).start()
            cc.tween(start).to(0.6,{scale:1},{easing:"backOut"}).start()
            await this.awaitTime(0.8);
            let self = this;
            let clickFunc = function(){
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.click)
                start.off("click");
                if(self._startAddCoin){
                    self._startAddCoin = false
                    winLable.stopAllActions()
                    let winCoinLabel = winLable.getComponent(cc.Label)
                    winCoinLabel.string = Global.FormatNumToComma(num)
                }
                show_popup.runAction(cc.sequence(cc.scaleTo(0.4, 0.3).easing(cc.easeBackIn()),
                    cc.callFunc(()=>{
                        self._popup.active = false;
                        show_popup.active = false;
                        sucess();
                    })));
            };
            cc.vv.gameData.checkAutoPlay(start, clickFunc);
            start.on("click", ()=>{
                start.stopAllActions();
                clickFunc();
            }); 
        });
    },


    async playEmoAnimation(bShowSmall=false){
        let character1 = cc.find("Canvas/safe_node/character");
        character1.active = false;
        let character2 = cc.find("Canvas/safe_node/Pick_Game_UI/Game_UI/xiaoemo_node/xiaoemo");
        character2.active = false;
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition2)
        this._transitionSpine2.active = true;
        let animation = this._transitionSpine2.getComponent(sp.Skeleton);
        animation.setAnimation(0,"skill01",false)
        animation.setCompleteListener(()=>{
            if(bShowSmall){
                animation.setAnimation(0,"idle",false)

                let norScale = this._transitionSpine2.scale;
                let norPos = this._transitionSpine2.position;
                let endPos = this._transitionSpine2.parent.convertToNodeSpaceAR(character2.convertToWorldSpaceAR(cc.v2(0,0)));
                cc.tween(this._transitionSpine2)
                    .to(0.5,{position:endPos, scale:character2.scale})
                    .call(()=>{
                        this._transitionSpine2.active = false;
                        this._transitionSpine2.scale = norScale;
                        this._transitionSpine2.position = norPos;
                        // character1.active = true;
                        character2.active = true;
                    })
                    .start()
            } else {
                this._transitionSpine2.active = false;
                character1.active = true;
                character2.active = true;
            }
        });
    },

    playLunpanAnimation(){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition1)
        this._transitionSpine1.active = true;
        let animation = this._transitionSpine1.getComponent(sp.Skeleton);
        animation.setAnimation(0,"animation",false)
        animation.setCompleteListener(()=>{
            this._transitionSpine1.active = false;
        });
    },

    showQiPaoMaoChu(){
        return new Promise((sucess,failed)=>{
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bubble_up)
            this._qipaomaochu.active = true
            let qipaoSp = this._qipaomaochu.getComponent(sp.Skeleton)
            qipaoSp.setAnimation(0,"animation",false)
            qipaoSp.setCompleteListener(()=>{
                this._qipaomaochu.active = false;
                sucess()
            });
        })
    },
